function inspect(t,...n){const r=[];for(let i=0;i<t.length;i++)r.push("cooked["+i+"]="+JSON.stringify(t[i])),r.push("raw["+i+"]="+JSON.stringify(t.raw[i])),i<n.length&&r.push("value["+i+"]="+JSON.stringify(n[i]));return r.join(" | ")}const x=42;function html(t,...n){return t.reduce(function(t,r,i){return t+r+(i<n.length?String(n[i]):"")},"")}function firstArgOnly(t){return t.length}print(inspect`a\n${x}b\tc${43}d`),print(html`<p>${"safe & sound"}</p>`),print("template with no substitutions has 1 string part:",firstArgOnly`no subs here`);